INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70000, 'wyl学院师资力量概况', '1', 'wyl学院现有专任教师760余人，其中教授82人、副教授216人，具有博士学位教师占比58%；拥有省级教学名师6人、省级科技创新团队4个。计算机学院现有专任教师128人，人工智能、软件工程等热门专业课程均由教授领衔授课。学校每年选派教师赴国内外高校访学与进修，近三年获省级以上教学成果奖9项。', '师资,教授,计算机学院', 'b50c17e4ed78f48b04582bc0fe925db81c8f500db5dee804c9bfff6b1aedd9ae', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70001, '学生宿舍介绍', '2', 'wyl学院学生宿舍分为4人间与6人间，均配备空调、独立卫浴、热水与无线网络。4人间为上床下桌组合家具，6人间为上下铺。门禁时间23:00至次日6:00，晚归需向宿管员登记。每栋楼配备宿管员、自助洗衣机与开水间。住宿费：4人间1500元/年，6人间1000元/年。宿舍设施报修通过宿管在线小程序提交，一般48小时内响应。', '宿舍,空调,住宿费', '0dcc315d351de5caa022adabe0bb4f6c2582ebda803c7085275597590e40f574', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70002, '食堂与餐饮服务', '3', 'wyl学院共有两个食堂与一处清真餐厅。第一食堂以基础大伙为主，人均8至12元；第二食堂设有麻辣香锅、煲仔饭、面食等风味档口，人均10至18元。营业时间：早餐6:30-9:30，午餐10:30-13:30，晚餐16:30-19:30，第二食堂夜宵窗口营业至22:00。支持校园一卡通、微信与支付宝支付。', '食堂,餐饮,营业时间', '0b2c285d6f88a4d5478fd44e43285b7f2ba912f2b4cae4176d8eb77aeb4d89a1', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70003, '学生请假管理制度', '4', 'wyl学院学生请假制度：1天以内由辅导员审批；1至3天由辅导员签署意见后报学院教学院长审批；3天以上须报教务处备案。病假需附医院证明，事假需说明具体事由。请假期间离校须履行登记手续，假期结束应及时销假。一学期事假累计超过课程总学时三分之一者，该课程不得参加期末考核。', '请假,制度,审批', 'a04557cb81c3fe9659d7c46f9bdc6586c19fee9d883c49b308b47b8e8e4b1334', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70004, '招生常见问题解答', '5', 'wyl学院招生常见问题：学费标准为普通专业4800元/年、艺术类专业9000元/年、中外合作办学18000元/年；住宿费1000至1500元/年。学校面向全国12个省份招生，院校代码3388，录取原则为分数优先、遵循志愿。新生可申请转专业，转出无门槛、转入需参加考核，于第一学年末统一办理。招生办咨询电话0571-88012345。', '招生,学费,转专业', 'bf4ceece66c355790fe4e0e8121378793992332dc5daa7346fd89a7cd952b91e', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70005, '图书馆与体育设施', '6', 'wyl学院图书馆馆藏纸质图书156万册、电子图书90万册，开放时间7:00-22:00，考试周延长至23:00。学生可借图书30册、借期30天，可续借1次。体育馆含游泳馆、篮球馆与健身房，凭一卡通免费或低收费预约，开放时间14:00-21:30。智慧教室覆盖全部教学楼，专业实验室晚间向预约学生开放。', '图书馆,体育馆,设施', '2abd27c491ff4b948a07cd175838c3ce84d885922e68c6de7e93a5f7fdb2ac9b', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70006, '校园网与一卡通使用指南', '7', 'wyl学院校园网账号为学生学号，初始密码为证件号后6位，登录自助服务平台后请及时修改；宿舍有线与无线网络已全覆盖，出口带宽10G。校园一卡通支持食堂消费、图书借阅、门禁与班车乘坐，可通过智慧校园APP在线充值（支持微信与支付宝），卡片遗失请第一时间在一卡通中心或APP上挂失。', '校园网,一卡通,充值', '177792e2e351ec841c8501401cbb3a26ff1f6cfd95f5580af75fe64395080411', '1', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70007, '教师答疑与办公安排', '1', '各专任教师每周安排不少于2小时的固定答疑时间，地点在各系办公室，具体时间表于开学第一周在教务系统公布。学生可通过教务系统教师信息栏目查询教师邮箱与办公地点。学业问题请优先联系任课教师，未能解决的由系教学秘书协调处理。', '答疑,办公,教师', '11312b80a38b1f9b17f7ddd7ce6cf473fbf82613429067c934138928adba7674', '0', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70008, '宿舍安全管理规定', '2', '宿舍内严禁使用电磁炉、电热锅等大功率电器，严禁私拉乱接电线，严禁存放易燃易爆物品；宿舍内吸烟一经发现按校纪处理。每学期组织消防演练不少于1次。发现安全隐患请立即报告宿管员，或拨打保卫处24小时值班电话0571-88011110。', '宿舍,安全,消防', '10771438679a13e873227ceec1a197a559c23e1efd6f7c49d09259cc92923840', '0', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_knowledge (id, title, category, content, tags, content_hash, status, publisher_id, create_by, create_time, update_by, update_time, del_flag) VALUES (70009, '2026年招生专业与计划增补', '5', 'wyl学院2026年新增智能科学与技术、数据科学与大数据技术两个本科专业，首批各招收90人；计算机科学与技术专业获批省级一流专业建设点，招生计划扩大至240人。具体分省分专业招生计划以各省教育考试院公布为准，考生可关注wyl学院招生网与官方微信公众号获取最新信息。', '招生,专业,计划', 'e94166720fec94134f24ca26898344d9654408a108a960e7254ae0ac378923d1', '0', 1, 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80000, '1', 120000, 1, 0, '经浙江省教育厅批准，wyl学院2026年面向全国12个省（自治区、直辖市）计划招收全日制普通本科生3200名，涵盖计算机科学与技术、软件工程、人工智能、电子信息工程等24个本科专业。学费标准：普通专业……', 'wyl学院2026年全日制普通本科招生简章', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80001, '2', 70000, 1, 0, 'wyl学院现有专任教师760余人，其中教授82人、副教授216人，具有博士学位教师占比58%；拥有省级教学名师6人、省级科技创新团队4个。计算机学院现有专任教师128人，人工智能、软件工程等热门专业课……', 'wyl学院师资力量概况', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80002, '1', 120001, 1, 0, '2026级新生请于9月6日8:00至17:00在wyl学院大学生活动中心办理报到手续，需携带录取通知书原件、身份证原件及复印件2份、纸质档案袋、一寸免冠照片8张，户口迁移证按自愿原则办理。学费与住宿费……', '2026级新生入学报到须知', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80003, '2', 70001, 1, 0, 'wyl学院学生宿舍分为4人间与6人间，均配备空调、独立卫浴、热水与无线网络。4人间为上床下桌组合家具，6人间为上下铺。门禁时间23:00至次日6:00，晚归需向宿管员登记。每栋楼配备宿管员、自助洗衣机……', '学生宿舍介绍', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80004, '1', 120002, 1, 0, '为优化住宿资源配置，现将2026-2027学年学生宿舍安排通知如下：学生公寓1至5号楼为4人间，上床下桌、独立卫浴、配备空调，住宿费1500元/年；6至9号楼为6人间，独立卫浴、配备空调，住宿费100……', '关于2026-2027学年学生宿舍安排的通知', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80005, '2', 70002, 1, 0, 'wyl学院共有两个食堂与一处清真餐厅。第一食堂以基础大伙为主，人均8至12元；第二食堂设有麻辣香锅、煲仔饭、面食等风味档口，人均10至18元。营业时间：早餐6:30-9:30，午餐10:30-13:3……', '食堂与餐饮服务', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80006, '1', 120003, 1, 0, '自9月1日起，wyl学院第一食堂营业时间调整为早餐6:30-9:00、午餐11:00-13:00、晚餐16:30-19:00；第二食堂与清真餐厅维持原时间：早餐6:30-9:30、午餐10:30-13……', '关于第一食堂营业时间调整的通知', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80007, '2', 70003, 1, 0, 'wyl学院学生请假制度：1天以内由辅导员审批；1至3天由辅导员签署意见后报学院教学院长审批；3天以上须报教务处备案。病假需附医院证明，事假需说明具体事由。请假期间离校须履行登记手续，假期结束应及时销假……', '学生请假管理制度', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80008, '1', 120004, 1, 0, 'wyl学院2025-2026学年奖学金评定工作定于9月10日启动。本次评定设国家奖学金8000元/人、国家励志奖学金5000元/人、校一等奖学金3000元/人、二等奖学金2000元/人、三等奖学金10……', '关于开展2025-2026学年奖学金评定的通知', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_chunk (id, source_type, source_id, source_version, chunk_index, content, title, url, status, create_by, create_time, update_by, update_time, del_flag) VALUES (80009, '2', 70004, 1, 0, 'wyl学院招生常见问题：学费标准为普通专业4800元/年、艺术类专业9000元/年、中外合作办学18000元/年；住宿费1000至1500元/年。学校面向全国12个省份招生，院校代码3388，录取原则……', '招生常见问题解答', '', '1', 1, NOW(), 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90000, 'demo-sess-0', '宿舍是几人间？有独立卫浴和空调吗？', 'wyl学院学生宿舍分为4人间与6人间，均配备空调、独立卫浴与热水。4人间为上床下桌组合家具，住宿费1500元/年；6人间住宿费1000元/年。宿舍楼设有自助洗衣机与开水间。', '80003', 1, 'deepseek-chat', 900, 180, 380, '192.168.0.100', '1', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90001, 'demo-sess-1', '学校食堂几点开门？有夜宵吗？', '第一食堂早餐6:30-9:00、午餐11:00-13:00、晚餐16:30-19:00；第二食堂与清真餐厅营业至19:30，第二食堂一楼夜宵窗口营业至22:00，支持校园一卡通、微信与支付宝支付。', '80005', 1, 'deepseek-chat', 1020, 225, 445, '192.168.0.100', '0', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90002, 'demo-sess-2', '新生报到需要带哪些材料？', '2026级新生9月6日在大学生活动中心报到，需携带录取通知书原件、身份证及复印件2份、纸质档案、一寸免冠照片8张，户口迁移证自愿办理；线上缴费后凭凭证领取宿舍钥匙与校园一卡通。', '80002,80000', 2, 'deepseek-chat', 1140, 270, 510, '192.168.0.100', '0', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90003, 'demo-sess-3', 'wyl学院学费一年多少钱？', 'wyl学院普通本科专业学费4800元/年，艺术类专业9000元/年，中外合作办学18000元/年；住宿费视房型为1000至1500元/年。', '80009', 1, 'deepseek-chat', 1260, 315, 575, '192.168.0.100', '1', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90004, 'demo-sess-4', '奖学金有哪些？怎么申请？', '设有国家奖学金8000元/人、国家励志奖学金5000元/人及校一、二、三等奖学金（3000/2000/1000元）。须于9月25日前在智慧校园奖助申请模块提交申请，综合测评位于班级前30%且必修课无不及格。', '80008', 1, 'deepseek-chat', 1380, 360, 640, '192.168.0.100', '0', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90005, 'demo-sess-5', '请假超过三天找谁审批？', '1天以内由辅导员审批；1至3天由辅导员签署意见后报学院教学院长审批；3天以上须报教务处备案。病假需附医院证明，假期结束应及时销假。', '80007', 1, 'deepseek-chat', 1500, 405, 705, '192.168.0.100', '0', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90006, 'demo-sess-6', '计算机学院师资力量怎么样？', 'wyl学院计算机学院有专任教师128人，人工智能、软件工程等热门专业课程均由教授领衔授课；全校有教授82人、副教授216人，博士学位教师占比58%，拥有省级教学名师6人。', '80001', 1, 'deepseek-chat', 1620, 450, 770, '192.168.0.100', '1', NULL, NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90007, 'demo-sess-7', '帮我写一首关于秋天的诗？', '抱歉，我只能回答与本校校园信息相关的问题～', '', 0, NULL, 0, 0, 835, '192.168.0.100', '0', 'out_of_scope', NOW(), 1, 1, NOW(), '0');
INSERT INTO campus_rag_log (id, session_id, question, answer, ref_ids, hit_count, model, prompt_tokens, completion_tokens, cost_time_ms, ip, feedback, refuse_reason, create_time, create_by, update_by, update_time, del_flag) VALUES (90008, 'demo-sess-8', '学校附近哪家股票值得买？', '暂时没有找到相关资料，建议查看校园公告或咨询教务处', '', 0, NULL, 0, 0, 900, '192.168.0.100', '0', 'no_context', NOW(), 1, 1, NOW(), '0');
