INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120000, 'wyl学院2026年全日制普通本科招生简章', '经浙江省教育厅批准，wyl学院2026年面向全国12个省（自治区、直辖市）计划招收全日制普通本科生3200名，涵盖计算机科学与技术、软件工程、人工智能、电子信息工程等24个本科专业。学费标准：普通专业4800元/年，艺术类专业9000元/年，住宿费1000至1500元/年。考生可于6月26日至7月2日登录省教育考试院志愿填报系统报考，院校代码3388，录取原则为分数优先、遵循志愿，录取结果7月中旬可在招生网查询。招生咨询热线0571-88012345，邮箱zsb@wyl.edu.cn。wyl学院招生办公室', '1', NULL, 1, '1', '1', DATE_SUB(NOW(), INTERVAL 1 DAY), NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120001, '2026级新生入学报到须知', '2026级新生请于9月6日8:00至17:00在wyl学院大学生活动中心办理报到手续，需携带录取通知书原件、身份证原件及复印件2份、纸质档案袋、一寸免冠照片8张，户口迁移证按自愿原则办理。学费与住宿费请于8月25日前登录智慧校园平台线上缴纳，报到当天凭缴费凭证领取宿舍钥匙与校园一卡通。家庭经济困难学生可现场申请绿色通道，并设生源地助学贷款咨询台。9月6日7:00至16:00，地铁1号线wyl学院站B出口与学校东门设有新生接站校车。咨询电话0571-88012789。wyl学院学生工作处', '1', NULL, 1, '1', '1', DATE_SUB(NOW(), INTERVAL 2 DAY), NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120002, '关于2026-2027学年学生宿舍安排的通知', '为优化住宿资源配置，现将2026-2027学年学生宿舍安排通知如下：学生公寓1至5号楼为4人间，上床下桌、独立卫浴、配备空调，住宿费1500元/年；6至9号楼为6人间，独立卫浴、配备空调，住宿费1000元/年。宿舍调整申请请于8月20日至9月5日登录智慧校园宿舍服务模块提交，逾期不再受理。宿舍门禁时间为23:00至次日6:00，晚归须向宿管员登记。设施报修通过宿管在线小程序提交，或拨打后勤值班电话0571-88013567。wyl学院后勤管理处', '1', NULL, 1, '0', '1', DATE_SUB(NOW(), INTERVAL 3 DAY), NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120003, '关于第一食堂营业时间调整的通知', '自9月1日起，wyl学院第一食堂营业时间调整为早餐6:30-9:00、午餐11:00-13:00、晚餐16:30-19:00；第二食堂与清真餐厅维持原时间：早餐6:30-9:30、午餐10:30-13:30、晚餐16:30-19:30，第二食堂一楼夜宵窗口营业至22:00。第一食堂已完成智慧餐台改造，支持自选称重结算，校园一卡通、微信、支付宝均可支付。师生对菜品质量与价格如有意见，可向饮食服务中心反馈，电话0571-88014233。wyl学院后勤管理处', '1', NULL, 1, '0', '1', DATE_SUB(NOW(), INTERVAL 4 DAY), NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120004, '关于开展2025-2026学年奖学金评定的通知', 'wyl学院2025-2026学年奖学金评定工作定于9月10日启动。本次评定设国家奖学金8000元/人、国家励志奖学金5000元/人、校一等奖学金3000元/人、二等奖学金2000元/人、三等奖学金1000元/人。申请条件：热爱祖国、品行端正，当学年必修课程无不及格记录，综合测评成绩位于班级前30%。学生须于9月25日前登录智慧校园奖助申请模块提交申请并上传成绩单，经班级民主评议、学院审核后公示5个工作日。政策咨询请联系学生资助管理中心0571-88015478。wyl学院学生工作处', '1', NULL, 1, '0', '1', DATE_SUB(NOW(), INTERVAL 5 DAY), NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120005, '计算机学院2026年专任教师招聘公告', '因学科建设与专业发展需要，wyl学院计算机学院面向社会公开招聘专任教师6名，其中教授或副教授2名、讲师4名，研究方向为人工智能、大数据、网络安全与软件工程。应聘者须具有博士学位，副教授及以上职称者原则上不超过45周岁。学校提供安家费15至60万元、科研启动经费5至20万元，并协助解决周转房与子女入学。报名截止2026年10月31日，简历请发送至rsc@wyl.edu.cn，邮件主题注明应聘计算机学院岗位与姓名。联系人：人事处王老师，电话0571-88016234。wyl学院人事处', '2', 50000, 1, '0', '0', NULL, NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120006, '计算机学院2026年秋季学期课程设计安排', '本学期课程设计安排如下：涉及数据结构、操作系统、数据库原理三门课程，实施周期为第9周至第16周。选题须于第8周周五前在实验教学平台确认，每组2至3人，成果须包含需求分析、设计文档与可运行源码三部分。中期检查安排在第12周，未参加者成绩作降档处理；验收答辩安排在第16周周四至周五，地点为实验楼A305、A307教室。指导教师分组名单与评分标准已在各班级群公布，如有疑问请联系计算机学院教务办0571-88017321。wyl学院计算机学院', '2', 50000, 1, '0', '0', NULL, NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120007, '关于组织学生参加2026年蓝桥杯程序设计大赛的通知', '2026年第十七届蓝桥杯全国软件和信息技术专业人才大赛报名工作已启动，wyl学院拟组织学生参加Python程序设计与C/C++程序设计两个组别。校内选拔赛定于10月中旬举行，通过选拔者由学院统一报名省赛并全额报销报名费。有意参赛的同学请于10月8日前将姓名、学号与参赛组别报送至所在班级辅导员处。赛前培训每周三晚19:00在实验楼B201举行，由陈志强老师主讲算法与真题解析。wyl学院人工智能学院', '2', 50002, 1, '0', '0', NULL, NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120008, '关于调整校园班车时刻表的通知', '自10月8日起，wyl学院校园班车运行方案调整如下：东门至教学楼线路7:00-18:00每15分钟一班；东门至地铁站线路早晚高峰（7:00-9:00、16:30-19:00）每10分钟一班，平峰每20分钟一班；周末及节假日仅保留东门至地铁站线路。乘车须出示校园一卡通，禁止携带易燃易爆物品。班车实时位置可在智慧校园校车服务模块查询，寒暑假停运。wyl学院后勤管理处', '1', NULL, 1, '0', '2', NULL, NOW(), NOW(), 1, 1, '0');
INSERT INTO campus_announcement (id, title, content, ann_type, target_department_id, publisher_id, is_top, status, publish_time, create_time, update_time, create_by, update_by, del_flag) VALUES (120009, '关于图书馆空调系统检修临时闭馆的通知', '因中央空调系统年度检修需要，图书馆定于10月12日8:00-18:00临时闭馆，当日19:00恢复开放。闭馆期间到期的图书归还日期自动顺延，线上预约的研修间自动取消且不扣信用分；数字资源（电子图书、知网等数据库）经校园网或VPN访问不受影响。由此带来的不便敬请谅解，如有疑问请拨打图书馆服务台电话0571-88017891。wyl学院图书馆', '1', NULL, 1, '0', '2', NULL, NOW(), NOW(), 1, 1, '0');
